package api

// Mission 04 keeps presentation separate from the persisted execution model.
const mission04Templates = `
{{define "run_detail"}}{{template "top" .}}
<header class="page-heading inspector-heading"><div><p class="eyebrow">{{tr .Lang "run_inspector_eyebrow"}}</p><h1>{{tr .Lang "run_inspector_title"}}</h1><p class="lead">{{tr .Lang "run_inspector_intro"}}</p></div><a class="button secondary" href="/ui/tenants/{{.Tenant}}/runs">← {{tr .Lang "run_back_to_history"}}</a></header>
{{if .RestoreBlocked}}<div class="alert error" role="status"><strong>{{tr .Lang "restore_blocked_title"}}</strong> {{tr .Lang "restore_blocked_body"}}</div>{{end}}
<section class="card run-summary" aria-labelledby="run-summary-title"><div class="section-head"><div><p class="eyebrow">{{tr .Lang "run_summary_eyebrow"}}</p><h2 id="run-summary-title">{{.Detail.EventType}}</h2><p class="muted">{{tr .Lang "run_ref"}} <code class="break-id">{{.Detail.ID}}</code></p></div><span class="badge {{.Detail.Status}}">{{tr .Lang (stageStatus .Detail.Status)}}</span></div>
<div class="run-facts"><div><small>{{tr .Lang "run_accepted"}}</small><strong>{{displayTime $.Lang .Detail.AcceptedAt.UTC true}}</strong></div><div><small>{{tr .Lang "run_planned"}}</small><strong>{{displayTime $.Lang .Detail.CreatedAt.UTC true}}</strong></div><div><small>{{tr .Lang "run_finished"}}</small><strong>{{if .Detail.FinishedAt}}{{displayTime $.Lang .Detail.FinishedAt.UTC true}}{{else}}{{tr .Lang "run_still_open"}}{{end}}</strong></div><div><small>{{tr .Lang "run_revision"}}</small><strong>#{{.Detail.Revision}}</strong></div></div>
<div class="run-source-line">{{if eq .Detail.StripeMode "test"}}<span class="badge">{{tr .Lang "run_test_mode"}}</span>{{end}}<span>{{tr .Lang "run_source"}}: {{tr .Lang (printf "source_%s" .Detail.EventSource)}}</span>{{if eq .Detail.Status "needs_attention"}}<span class="badge needs_attention">{{tr .Lang "run_manual_attention"}}</span>{{end}}</div></section>
<section class="card journey-panel" aria-labelledby="journey-title"><div class="section-head"><div><p class="eyebrow">{{tr .Lang "run_journey_eyebrow"}}</p><h2 id="journey-title">{{tr .Lang "run_journey_title"}}</h2></div><span class="muted">{{tr .Lang "run_journey_hint"}}</span></div><ol class="run-journey">{{range .RunStages}}<li class="journey-stage {{.Status}}"><span class="provider-emblem {{.Provider}}" aria-hidden="true">{{if eq .Provider "stripe"}}S{{else if eq .Provider "hubspot"}}H{{else}}#{{end}}</span><div><small>{{if eq .Provider "stripe"}}01 / {{tr $.Lang "run_source_stage"}}{{else if eq .Provider "hubspot"}}02 / {{tr $.Lang "run_crm_stage"}}{{else}}03 / {{tr $.Lang "run_notify_stage"}}{{end}}</small><strong>{{if eq .Provider "stripe"}}Stripe{{else if eq .Provider "hubspot"}}{{tr $.Lang "run_step_crm"}}{{else}}{{tr $.Lang "run_step_slack"}}{{end}}</strong><span class="badge {{.Status}}">{{tr $.Lang (stageStatus .Status)}}</span><p>{{tr $.Lang .Explanation}}</p>{{if .Action}}<small>{{tr $.Lang "run_attempts"}}: {{.Action.Attempts}}{{if .Action.NextAttemptAt}} · {{tr $.Lang "run_next_retry"}} {{displayTime $.Lang .Action.NextAttemptAt.UTC true}}{{end}}</small>{{end}}</div></li>{{end}}</ol></section>
<div class="run-inspector-grid"><section class="card" aria-labelledby="run-context-title"><p class="eyebrow">{{tr .Lang "run_context_eyebrow"}}</p><h2 id="run-context-title">{{tr .Lang "run_context_title"}}</h2><dl class="detail-list"><dt>{{tr .Lang "run_stripe_event"}}</dt><dd>{{if stripeEventURL .Detail.EventID}}<a href="{{stripeEventURL .Detail.EventID}}" rel="noopener noreferrer" target="_blank"><code class="break-id">{{.Detail.EventID}}</code></a>{{else}}<code class="break-id">{{.Detail.EventID}}</code>{{end}}</dd><dt>{{tr .Lang "run_customer"}}</dt><dd><code class="break-id">{{.Detail.CustomerID}}</code></dd><dt>{{tr .Lang "run_invoice"}}</dt><dd>{{if .Detail.InvoiceID}}<code class="break-id">{{.Detail.InvoiceID}}</code>{{else}}{{tr .Lang "run_no_invoice"}}{{end}}</dd><dt>{{tr .Lang "run_managed_key"}}</dt><dd><code class="break-id">{{.Detail.CustomerKey}}</code></dd><dt>{{tr .Lang "run_revision_id"}}</dt><dd><code class="break-id">{{.Detail.RevisionID}}</code></dd></dl></section>
<section class="card" aria-labelledby="run-timeline-title"><p class="eyebrow">{{tr .Lang "run_timeline_eyebrow"}}</p><h2 id="run-timeline-title">{{tr .Lang "run_timeline_title"}}</h2><ol class="event-timeline">{{range .RunTimeline}}<li><time datetime="{{.At.UTC.Format "2006-01-02T15:04:05Z"}}">{{displayTime $.Lang .At.UTC true}}</time><strong>{{tr $.Lang .Label}}</strong><span class="break-id">{{timelineNote $.Lang .Note}}</span></li>{{end}}</ol></section></div>
<section class="run-actions" aria-labelledby="run-actions-title"><div class="section-head"><div><p class="eyebrow">{{tr .Lang "run_actions_eyebrow"}}</p><h2 id="run-actions-title">{{tr .Lang "run_actions_title"}}</h2></div></div>
{{if .Detail.Actions}}{{range .Detail.Actions}}<article class="card action-panel {{.Status}}"><div class="section-head"><div><h3>{{if eq .Kind "crm_projection"}}{{tr $.Lang "run_step_crm"}}{{else}}{{tr $.Lang "run_step_slack"}}{{end}}</h3><p class="muted">{{tr $.Lang "run_action_id"}} <code class="break-id">{{.ID}}</code></p></div><span class="badge {{.Status}}">{{tr $.Lang (stageStatus .Status)}}</span></div>
<p class="action-explanation">{{runError $.Lang .ErrorClass}}</p>{{if .DependsOn}}<p class="hint">{{tr $.Lang "run_depends_on_crm"}} <code class="break-id">{{.DependsOn}}</code></p>{{end}}
<div class="action-facts"><span>{{tr $.Lang "run_attempts"}} <strong>{{.Attempts}}</strong></span>{{if .NextAttemptAt}}<span>{{tr $.Lang "run_next_retry"}} <strong>{{displayTime $.Lang .NextAttemptAt.UTC true}}</strong></span>{{end}}{{if .FirstFailedAt}}<span>{{tr $.Lang "run_first_failure"}} <strong>{{displayTime $.Lang .FirstFailedAt.UTC true}}</strong></span>{{end}}{{if .ContactID}}<span>{{tr $.Lang "run_confirmed_contact"}} <strong>{{if hubspotContactURL $.HubSpotPortal .ContactID}}<a href="{{hubspotContactURL $.HubSpotPortal .ContactID}}" target="_blank" rel="noopener noreferrer">{{.ContactID}}</a>{{else}}<code>{{.ContactID}}</code>{{end}}</strong></span>{{end}}{{if .SlackTS}}<span>{{tr $.Lang "run_confirmed_message"}} <strong>{{if slackMessageURL .SlackChannel .SlackTS}}<a href="{{slackMessageURL .SlackChannel .SlackTS}}" target="_blank" rel="noopener noreferrer"><code>{{.SlackChannel}} / {{.SlackTS}}</code></a>{{else}}<code>{{.SlackChannel}} / {{.SlackTS}}</code>{{end}}</strong></span>{{end}}</div>
{{if and (eq .Kind "crm_projection") $.CRMNoWrite}}<p class="hint">{{tr $.Lang "run_crm_no_write_explanation"}}</p>{{end}}
{{if $.CanOperate}}{{if and (eq .Kind "crm_projection") (eq .Status "needs_attention")}}<a class="button secondary" href="/ui/tenants/{{$.Tenant}}/runs/{{$.Detail.ID}}/mapping">{{tr $.Lang "run_review_mapping"}}</a>{{end}}
{{if or (eq .Status "dead") (eq .Status "needs_attention") (eq .Status "blocked_auth") (eq .Status "blocked_config")}}<details class="recovery-disclosure"><summary>{{tr $.Lang "run_retry_action"}}</summary><p>{{tr $.Lang "run_retry_explanation"}}</p><form method="post" action="/ui/tenants/{{$.Tenant}}/runs/{{$.Detail.ID}}/actions/{{.ID}}/recover" data-confirm-title="{{tr $.Lang "run_confirm_retry"}}" data-confirm-body="{{tr $.Lang "run_retry_explanation"}}" data-confirm-target="{{.ID}}" data-confirm-action="{{tr $.Lang "run_confirm_retry"}}"><input type="hidden" name="csrf_token" value="{{$.CSRF}}"><input type="hidden" name="generation" value="{{.Generation}}"><input type="hidden" name="decision" value="manual_retry"><label for="reason-{{.ID}}">{{tr $.Lang "run_retry_reason"}}</label><textarea id="reason-{{.ID}}" name="reason" maxlength="1000" required></textarea><button>{{tr $.Lang "run_confirm_retry"}}</button></form></details>{{end}}
{{if and (eq .Status "unknown") (ne .Kind "crm_projection")}}<div class="alert" role="status"><strong>{{tr $.Lang "run_unknown_warning_title"}}</strong> {{tr $.Lang "run_unknown_warning"}}</div><div class="unknown-actions"><details class="recovery-disclosure"><summary>{{tr $.Lang "run_confirm_delivery"}}</summary><form method="post" action="/ui/tenants/{{$.Tenant}}/runs/{{$.Detail.ID}}/actions/{{.ID}}/recover" data-confirm-title="{{tr $.Lang "run_confirm_delivery"}}" data-confirm-body="{{tr $.Lang "confirm_unknown_body"}}" data-confirm-target="{{.ID}}" data-confirm-action="{{tr $.Lang "run_confirm_existing_message"}}"><input type="hidden" name="csrf_token" value="{{$.CSRF}}"><input type="hidden" name="generation" value="{{.Generation}}"><input type="hidden" name="decision" value="confirm_unknown"><label for="confirm-reason-{{.ID}}">{{tr $.Lang "run_observation_reason"}}</label><textarea id="confirm-reason-{{.ID}}" name="reason" maxlength="1000" required></textarea><label for="unknown-channel-{{.ID}}">{{tr $.Lang "run_observed_channel"}}</label><input id="unknown-channel-{{.ID}}" name="external_channel" value="{{$.Detail.Config.SlackChannelID}}" required><label for="unknown-ts-{{.ID}}">{{tr $.Lang "run_observed_ts"}}</label><input id="unknown-ts-{{.ID}}" name="external_ts" placeholder="1234567890.123456" pattern="[0-9]{10,16}\.[0-9]{6}" required><button>{{tr $.Lang "run_confirm_existing_message"}}</button></form></details>
<details class="recovery-disclosure"><summary>{{tr $.Lang "run_leave_unknown"}}</summary><form method="post" action="/ui/tenants/{{$.Tenant}}/runs/{{$.Detail.ID}}/actions/{{.ID}}/recover"><input type="hidden" name="csrf_token" value="{{$.CSRF}}"><input type="hidden" name="generation" value="{{.Generation}}"><input type="hidden" name="decision" value="leave_unknown"><label for="leave-reason-{{.ID}}">{{tr $.Lang "run_observation_reason"}}</label><textarea id="leave-reason-{{.ID}}" name="reason" maxlength="1000" required></textarea><button class="secondary">{{tr $.Lang "run_leave_unknown"}}</button></form></details>
<details class="recovery-disclosure danger-zone"><summary>{{tr $.Lang "run_risk_retry"}}</summary><p>{{tr $.Lang "run_risk_retry_warning"}}</p><form method="post" action="/ui/tenants/{{$.Tenant}}/runs/{{$.Detail.ID}}/actions/{{.ID}}/recover" data-confirm-title="{{tr $.Lang "run_risk_retry"}}" data-confirm-body="{{tr $.Lang "run_risk_retry_warning"}}" data-confirm-target="{{.ID}}" data-confirm-action="{{tr $.Lang "run_risk_retry"}}" data-confirm-level="danger"><input type="hidden" name="csrf_token" value="{{$.CSRF}}"><input type="hidden" name="generation" value="{{.Generation}}"><input type="hidden" name="decision" value="risk_retry"><label for="risk-reason-{{.ID}}">{{tr $.Lang "run_observation_reason"}}</label><textarea id="risk-reason-{{.ID}}" name="reason" maxlength="1000" required></textarea><label class="check-row"><input type="checkbox" name="ack_risk" value="true" required> {{tr $.Lang "run_ack_duplicate"}}</label><button class="danger">{{tr $.Lang "run_risk_retry"}}</button></form></details></div>{{end}}{{end}}
<details class="diagnostic-disclosure"><summary>{{tr $.Lang "run_attempt_details"}}</summary>{{if .Timeline}}<ol class="timeline">{{range .Timeline}}<li><strong>{{tr $.Lang "run_attempt"}} #{{.Number}}</strong> · {{displayTime $.Lang .StartedAt.UTC true}} · {{tr $.Lang (stageStatus .Outcome)}}{{if .RequestStartedAt}}<p>{{tr $.Lang "run_external_gate"}} {{displayTime $.Lang .RequestStartedAt.UTC true}}</p>{{end}}{{if .Calls}}<ul>{{range .Calls}}<li>{{.Provider}} {{.Method}} <code class="break-id">{{.Path}}</code>{{if .Status}} · HTTP {{.Status}}{{else if .Outcome}} · {{.Outcome}}{{end}}{{if .RequestID}} · {{tr $.Lang "run_request_ref"}} <code class="break-id">{{.RequestID}}</code>{{end}}</li>{{end}}</ul>{{end}}</li>{{end}}</ol>{{else}}<p class="muted">{{tr $.Lang "run_no_attempts"}}</p>{{end}}</details>
<details class="diagnostic-disclosure"><summary>{{tr $.Lang "run_operator_decisions"}}</summary>{{if .Decisions}}<ol class="timeline">{{range .Decisions}}<li>{{displayTime $.Lang .CreatedAt.UTC false}} · {{timelineNote $.Lang .Decision}} · {{tr $.Lang (stageStatus .FromStatus)}} → {{tr $.Lang (stageStatus .ToStatus)}}<p>{{.Reason}}</p></li>{{end}}</ol>{{else}}<p class="muted">{{tr $.Lang "run_no_decisions"}}</p>{{end}}</details></article>{{end}}{{else}}<div class="card empty-state">{{tr .Lang "run_no_actions"}}</div>{{end}}</section>
<section class="card"><h2>{{tr .Lang "run_audit_title"}}</h2>{{if .Detail.Audit}}<ol class="audit-list">{{range .Detail.Audit}}<li><time>{{displayTime $.Lang .CreatedAt.UTC false}}</time><span>{{auditLabel $.Lang .Operation .Result}}</span><code class="break-id">{{.TargetID}}</code></li>{{end}}</ol>{{else}}<p class="muted">{{tr .Lang "run_no_audit"}}</p>{{end}}</section>{{if not .CanOperate}}<p class="muted">{{tr .Lang "run_viewer_note"}}</p>{{end}}{{template "bottom" .}}{{end}}

{{define "mapping"}}{{template "top" .}}<header class="page-heading"><p class="eyebrow">{{tr .Lang "mapping_eyebrow"}}</p><h1>{{tr .Lang "mapping_title"}}</h1><p class="lead">{{tr .Lang "mapping_intro"}}</p></header><section class="card"><h2>{{tr .Lang "mapping_identity"}}</h2><dl class="detail-list"><dt>{{tr .Lang "run_customer"}}</dt><dd><code class="break-id">{{.Detail.CustomerID}}</code></dd><dt>{{tr .Lang "run_managed_key"}}</dt><dd><code class="break-id">{{.Detail.CustomerKey}}</code></dd><dt>{{tr .Lang "mapping_hubspot_connection"}}</dt><dd><code class="break-id">{{.Detail.Config.HubSpotConnectionID}}</code></dd><dt>{{tr .Lang "mapping_current_link"}}</dt><dd>{{if .HasLink}}<code>{{.Link.ContactID}}</code> · {{.Link.Source}}{{else}}{{tr .Lang "mapping_no_link"}}{{end}}</dd></dl><div class="alert">{{tr .Lang "mapping_archive_warning"}}</div></section>
{{if .CanOperate}}<section class="card"><h2>{{tr .Lang "mapping_inspect"}}</h2><form class="mapping-inspect-form" method="get"><label for="contact-id">{{tr .Lang "mapping_contact_id"}}</label><input id="contact-id" name="contact_id" inputmode="numeric" pattern="[0-9]{1,32}" value="{{.CandidateID}}" required><button class="secondary">{{tr .Lang "mapping_read_contact"}}</button></form>{{if .HasPreview}}<div class="alert {{if eq .Preview.IdentityStatus "conflict"}}error{{else}}success{{end}}" role="status"><strong>{{tr .Lang "mapping_contact"}} {{.Preview.ID}}</strong><p>{{tr .Lang "mapping_identity_status"}}: {{tr .Lang (printf "mapping_status_%s" .Preview.IdentityStatus)}}</p><p class="hint">{{tr .Lang (printf "mapping_status_explain_%s" .Preview.IdentityStatus)}}</p><p>{{tr .Lang "run_managed_key"}}: {{if .Preview.CustomerKey}}<code class="break-id">{{.Preview.CustomerKey}}</code>{{else}}{{tr .Lang "mapping_key_unset"}}{{end}}</p></div>{{if ne .Preview.IdentityStatus "conflict"}}<h2>{{tr .Lang "mapping_bind"}}</h2><form class="mapping-bind-form" method="post" data-confirm-title="{{tr .Lang "mapping_bind_button"}}" data-confirm-body="{{tr .Lang "confirm_mapping_body"}}" data-confirm-target="{{.Preview.ID}}" data-confirm-action="{{tr .Lang "mapping_bind_button"}}"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="contact_id" value="{{.Preview.ID}}"><label for="mapping-reason">{{tr .Lang "mapping_reason"}}</label><textarea id="mapping-reason" name="reason" minlength="3" maxlength="1000" required></textarea><button>{{tr .Lang "mapping_bind_button"}}</button></form>{{end}}{{end}}</section>{{else}}<p class="muted">{{tr .Lang "run_viewer_note"}}</p>{{end}}<a href="/ui/tenants/{{.Tenant}}/runs/{{.Detail.ID}}">← {{tr .Lang "run_inspector_title"}}</a>{{template "bottom" .}}{{end}}
{{define "reconciliation"}}{{template "top" .}}
<header class="page-heading"><p class="eyebrow">{{tr .Lang "reconcile_eyebrow"}}</p><h1>{{tr .Lang "reconcile_title"}}</h1><p class="lead">{{tr .Lang "reconcile_intro"}}</p></header>
<section class="card reconcile-health {{.ReconcileState}}" aria-labelledby="reconcile-health-title"><div class="section-head"><div><p class="eyebrow">{{tr .Lang "reconcile_health_eyebrow"}}</p><h2 id="reconcile-health-title">{{tr .Lang (printf "reconcile_state_%s" .ReconcileState)}}</h2><p>{{tr .Lang (printf "reconcile_state_body_%s" .ReconcileState)}}</p></div><span class="badge {{.ReconcileState}}">{{tr .Lang (printf "reconcile_state_%s" .ReconcileState)}}</span></div>
<div class="reconcile-kpis"><div><small>{{tr .Lang "reconcile_last_complete"}}</small><strong>{{if .LastCompleteAt}}{{displayTime $.Lang .LastCompleteAt.UTC false}}{{else}}{{tr .Lang "reconcile_never_verified"}}{{end}}</strong></div><div><small>{{tr .Lang "reconcile_gap_count"}}</small><strong>{{.CoverageGaps}}</strong></div><div><small>{{tr .Lang "reconcile_outbox_age"}}</small><strong>{{displayDuration $.Lang .Operational.OldestOutboxSeconds}}</strong></div><div><small>{{tr .Lang "reconcile_overdue_age"}}</small><strong>{{displayDuration $.Lang .Operational.OldestDueSeconds}}</strong></div></div></section>
{{if not .Operational.OutboundEnabled}}<div class="alert error" role="status"><strong>{{tr .Lang "restore_blocked_title"}}</strong> {{tr .Lang "restore_blocked_body"}}</div>{{end}}
<div class="reconcile-grid"><section class="card" aria-labelledby="coverage-title"><div class="section-head"><div><p class="eyebrow">{{tr .Lang "reconcile_coverage_eyebrow"}}</p><h2 id="coverage-title">{{tr .Lang "reconcile_coverage_title"}}</h2></div></div>{{if .Operational.Checkpoints}}<div class="coverage-list">{{range .Operational.Checkpoints}}<article class="coverage-row {{if .GapCode}}degraded{{else if .LastCompleteAt}}healthy{{else}}unverified{{end}}"><div><strong>{{tr $.Lang (printf "checkpoint_%s" .Kind)}}</strong><small><code class="break-id">{{.ConnectionID}}</code></small></div><span class="badge {{if .GapCode}}degraded{{else if .LastCompleteAt}}healthy{{else}}unverified{{end}}">{{if .GapCode}}{{tr $.Lang "reconcile_gap"}}{{else if .LastCompleteAt}}{{tr $.Lang "reconcile_checkpoint_recorded"}}{{else}}{{tr $.Lang "reconcile_not_complete"}}{{end}}</span><p>{{tr $.Lang "reconcile_window"}}: {{displayTime $.Lang .WindowStart.UTC false}} – {{displayTime $.Lang .WindowEnd.UTC false}}</p><p>{{tr $.Lang "reconcile_scanned_discovered"}}: {{.ScannedCount}} / {{.DiscoveredCount}}</p>{{if .LastCompleteAt}}<p>{{tr $.Lang "reconcile_last_complete"}}: {{displayTime $.Lang .LastCompleteAt.UTC false}}</p>{{end}}{{if .GapCode}}<p class="coverage-warning">{{tr $.Lang "reconcile_gap_reason"}}: <code>{{.GapCode}}</code>. {{tr $.Lang "reconcile_gap_not_proven"}}</p>{{end}}</article>{{end}}</div>{{else}}<div class="empty-state"><strong>{{tr .Lang "reconcile_no_history_title"}}</strong><p>{{tr .Lang "reconcile_no_history_body"}}</p></div>{{end}}<p class="hint">{{tr .Lang "reconcile_coverage_limit"}}</p></section>
<section class="card" aria-labelledby="processing-title"><p class="eyebrow">{{tr .Lang "reconcile_processing_eyebrow"}}</p><h2 id="processing-title">{{tr .Lang "reconcile_processing_title"}}</h2><div class="processing-list"><div><span>{{tr .Lang "reconcile_unknown_actions"}}</span><strong>{{.Operational.UnknownActions}}</strong><small>{{tr .Lang "reconcile_oldest"}} {{displayDuration $.Lang .Operational.OldestUnknownSeconds}}</small></div><div><span>{{tr .Lang "reconcile_dead_actions"}}</span><strong>{{.Operational.DeadActions}}</strong><small>{{tr .Lang "reconcile_oldest"}} {{displayDuration $.Lang .Operational.OldestDeadSeconds}}</small></div><div><span>{{tr .Lang "reconcile_overdue_age"}}</span><strong>{{displayDuration $.Lang .Operational.OldestDueSeconds}}</strong><small>{{tr .Lang "reconcile_retry_note"}}</small></div></div>{{if or (gt .Operational.UnknownActions 0) (gt .Operational.DeadActions 0)}}<div class="attention-callout"><strong>{{tr .Lang "reconcile_attention_title"}}</strong><p>{{tr .Lang "reconcile_attention_body"}}</p><a href="/ui/tenants/{{.Tenant}}/runs">{{tr .Lang "reconcile_open_runs"}} →</a></div>{{end}}{{if .CoverageGaps}}<div class="attention-callout"><strong>{{tr .Lang "reconcile_gap_attention_title"}}</strong><p>{{tr .Lang "reconcile_gap_not_proven"}}</p></div>{{end}}</section></div>
<section class="card" aria-labelledby="scan-title"><div class="section-head"><div><p class="eyebrow">{{tr .Lang "reconcile_scan_eyebrow"}}</p><h2 id="scan-title">{{tr .Lang "reconcile_scan_title"}}</h2><p class="muted">{{tr .Lang "reconcile_scan_intro"}}</p></div></div><div class="policy-note">{{tr .Lang "reconcile_no_retro_slack"}}</div>
{{if .CanOperate}}{{if .HasReconcileConnection}}<form class="reconcile-form" method="post" action="/ui/tenants/{{.Tenant}}/reconciliation/preview"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><div class="form-section"><span class="form-section-index">01</span><div><h3>{{tr .Lang "reconcile_choose_connection"}}</h3><p class="hint">{{tr .Lang "reconcile_connection_help"}}</p></div></div><label for="reconcile-stripe">{{tr .Lang "reconcile_stripe_connection"}}</label><select id="reconcile-stripe" name="connection_id" required data-required-message="{{tr .Lang "reconcile_connection_required"}}"><option value="" disabled {{if not .HistoricalDraft.Connection}}selected{{end}}>{{tr .Lang "reconcile_choose_connection"}}</option>{{range .ReconcileConnections}}<option value="{{.ID}}" {{if eq $.HistoricalDraft.Connection .ID}}selected{{end}}>{{.ProviderAccountID}} · {{tr $.Lang .Environment}}</option>{{end}}</select>
<div class="form-section"><span class="form-section-index">02</span><div><h3>{{tr .Lang "reconcile_choose_window"}}</h3><p class="hint">{{tr .Lang "reconcile_window_help"}}</p></div></div><div class="row"><div><label for="reconcile-from">{{tr .Lang "reconcile_from_utc"}}</label><input id="reconcile-from" name="from_at" type="datetime-local" step="1" data-date-label="{{tr .Lang "reconcile_date_utc"}}" data-time-label="{{tr .Lang "reconcile_time_utc"}}" data-calendar-hint="{{tr .Lang "reconcile_calendar_hint"}}" data-picker-invalid="{{tr .Lang "reconcile_picker_invalid"}}" value="{{.HistoricalDraft.From}}" required></div><div><label for="reconcile-to">{{tr .Lang "reconcile_to_utc"}}</label><input id="reconcile-to" name="to_at" type="datetime-local" step="1" data-date-label="{{tr .Lang "reconcile_date_utc"}}" data-time-label="{{tr .Lang "reconcile_time_utc"}}" data-calendar-hint="{{tr .Lang "reconcile_calendar_hint"}}" data-picker-invalid="{{tr .Lang "reconcile_picker_invalid"}}" value="{{.HistoricalDraft.To}}" required></div></div><p class="hint">{{tr .Lang "reconcile_utc_help"}}</p><label for="reconcile-max">{{tr .Lang "reconcile_max_events"}}</label><input id="reconcile-max" name="max_events" type="number" min="1" max="500" value="{{.HistoricalDraft.Max}}" required><p class="hint">{{tr .Lang "reconcile_max_help"}}</p><label for="reconcile-reason">{{tr .Lang "reconcile_audit_reason"}}</label><textarea id="reconcile-reason" name="reason" minlength="12" maxlength="500" required>{{.HistoricalDraft.Reason}}</textarea><p class="hint">{{tr .Lang "reconcile_reason_help"}}</p><button>{{tr .Lang "reconcile_review_bounds"}}</button></form>{{else}}<div class="empty-state">{{tr .Lang "reconcile_no_connection"}}</div>{{end}}{{else}}<p class="muted">{{tr .Lang "reconcile_viewer_note"}}</p>{{end}}</section>
<section class="card" aria-labelledby="request-history-title"><div class="section-head"><div><p class="eyebrow">{{tr .Lang "reconcile_requests_eyebrow"}}</p><h2 id="request-history-title">{{tr .Lang "reconcile_requests_title"}}</h2><p class="muted">{{tr .Lang "reconcile_requests_intro"}}</p></div></div>{{if .Operational.Requests}}<div class="request-list">{{range .Operational.Requests}}<article class="request-row"><div class="section-head"><strong>{{displayTime $.Lang .CreatedAt.UTC false}}</strong><span class="badge {{.Status}}">{{tr $.Lang (printf "request_%s" .Status)}}</span></div><p>{{tr $.Lang "reconcile_window"}}: {{displayTime $.Lang .FromAt.UTC false}} – {{displayTime $.Lang .ToAt.UTC false}}</p><p>{{tr $.Lang "reconcile_scanned_limit"}}: {{.Scanned}} / {{.MaxEvents}} · {{tr $.Lang "reconcile_discovered"}}: {{.Discovered}}</p>{{if .GapCode}}<p class="coverage-warning">{{tr $.Lang "reconcile_gap_reason"}}: <code>{{.GapCode}}</code></p>{{end}}{{if .FinishedAt}}<p>{{tr $.Lang "reconcile_finished"}}: {{displayTime $.Lang .FinishedAt.UTC false}}</p>{{end}}<details class="diagnostic-disclosure"><summary>{{tr $.Lang "reconcile_request_details"}}</summary><dl class="detail-list"><dt>{{tr $.Lang "reconcile_stripe_connection"}}</dt><dd><code class="break-id">{{.ConnectionID}}</code></dd><dt>{{tr $.Lang "reconcile_operator"}}</dt><dd><code class="break-id">{{.ActorID}}</code></dd><dt>{{tr $.Lang "reconcile_audit_reason"}}</dt><dd>{{.Reason}}</dd><dt>{{tr $.Lang "reconcile_request_id"}}</dt><dd><code class="break-id">{{.ID}}</code></dd></dl></details></article>{{end}}</div>{{if .Operational.NextRequestCursor}}<a class="button secondary" href="/ui/tenants/{{.Tenant}}/reconciliation?history_cursor={{.Operational.NextRequestCursor}}">{{tr .Lang "reconcile_older_requests"}}</a>{{end}}{{else}}<div class="empty-state">{{tr .Lang "reconcile_no_requests"}}</div>{{end}}</section>{{template "bottom" .}}{{end}}

{{define "reconciliation_preview"}}{{template "top" .}}<header class="page-heading"><p class="eyebrow">{{tr .Lang "reconcile_preview_eyebrow"}}</p><h1>{{tr .Lang "reconcile_preview_title"}}</h1><p class="lead">{{tr .Lang "reconcile_preview_intro"}}</p></header><section class="card preview-panel"><div class="section-head"><h2>{{tr .Lang "reconcile_effective_bounds"}}</h2><span class="badge unverified">{{tr .Lang "reconcile_not_started"}}</span></div><dl class="detail-list"><dt>{{tr .Lang "reconcile_stripe_connection"}}</dt><dd><code class="break-id">{{.Historical.ConnectionID}}</code></dd><dt>{{tr .Lang "reconcile_from_utc"}}</dt><dd>{{displayTime $.Lang .Historical.FromAt.UTC true}}</dd><dt>{{tr .Lang "reconcile_to_utc"}}</dt><dd>{{displayTime $.Lang .Historical.ToAt.UTC true}}</dd><dt>{{tr .Lang "reconcile_max_events"}}</dt><dd>{{.Historical.MaxEvents}} · {{tr .Lang "reconcile_up_to_pages"}} {{.EstimatedPages}}</dd><dt>{{tr .Lang "reconcile_audit_reason"}}</dt><dd>{{.Historical.Reason}}</dd></dl><div class="policy-note">{{tr .Lang "reconcile_no_retro_slack"}}</div><p class="hint">{{tr .Lang "reconcile_preview_limit_note"}}</p><form method="post" action="/ui/tenants/{{.Tenant}}/reconciliation" data-confirm-title="{{tr .Lang "reconcile_request_scan"}}" data-confirm-body="{{tr .Lang "confirm_reconcile_body"}}" data-confirm-target="{{.Historical.ConnectionID}}" data-confirm-action="{{tr .Lang "reconcile_request_scan"}}"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="connection_id" value="{{.Historical.ConnectionID}}"><input type="hidden" name="from_at" value="{{.Historical.FromAt.UTC.Format "2006-01-02T15:04:05Z"}}"><input type="hidden" name="to_at" value="{{.Historical.ToAt.UTC.Format "2006-01-02T15:04:05Z"}}"><input type="hidden" name="max_events" value="{{.Historical.MaxEvents}}"><input type="hidden" name="reason" value="{{.Historical.Reason}}"><button>{{tr .Lang "reconcile_request_scan"}}</button> <a class="button secondary" href="/ui/tenants/{{.Tenant}}/reconciliation">{{tr .Lang "reconcile_edit_bounds"}}</a></form></section>{{template "bottom" .}}{{end}}
`
